package app.dshmobile.android;
import android.content.Intent;import android.content.Context;import android.app.Instrumentation;import android.widget.*;import android.view.View;import android.view.ViewGroup;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.JSONObject;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class DeviceTest {
 @Test public void validatesPairingAndLoadsNativeABI()throws Exception {assertFalse(NativeLink.run(new JSONObject().put("Op","close")).has("Error"));try{NativeLink.offer("dshmobile://pair?v=9");fail();}catch(Exception expected){} }
 @Test public void launchesAndFitsWindow(){Instrumentation i=InstrumentationRegistry.getInstrumentation();Context c=i.getTargetContext();MainActivity a=(MainActivity)i.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();i.runOnMainSync(()->{assertTrue(a.body.getWidth()>0);assertTrue(a.body.getChildCount()>0);assertEquals(a.root.getWidth()-a.root.getPaddingLeft()-a.root.getPaddingRight(),a.body.getWidth());a.finish();});}
 @Test public void pairsPinsReconnectsAndOpensWebSocket() throws Exception {
  String pin=InstrumentationRegistry.getArguments().getString("pin");assertNotNull(pin);Instrumentation i=InstrumentationRegistry.getInstrumentation();
  JSONObject q=NativeLink.offer("dshmobile://pair?v=1&id=instrumentation-peer&fp="+pin+"&h=127.0.0.1:39463&c=integration-code-123");q.put("Op","pair").put("Device","android-test");JSONObject bad=new JSONObject(q.toString()).put("Pin","AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA");assertTrue(NativeLink.run(bad).has("Error"));JSONObject paired=NativeLink.run(q);assertTrue(paired.optString("Error"),paired.has("Token"));q.put("Token",paired.getString("Token")).put("Op","open");JSONObject link=NativeLink.run(q);assertTrue(link.optString("Error"),link.has("Origin"));assertEquals(link.getString("Origin"),NativeLink.run(q).getString("Origin"));
  java.net.HttpURLConnection denied=(java.net.HttpURLConnection)new java.net.URL(link.getString("Origin")+"/").openConnection();assertEquals(403,denied.getResponseCode());denied.disconnect();
  // Save the pair and let the real cold-start path restore it without tapping anything.
  Vault vault=new Vault(i.getTargetContext());vault.save(q);long start=android.os.SystemClock.elapsedRealtime();MainActivity a=(MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{java.util.concurrent.atomic.AtomicBoolean ok=new java.util.concurrent.atomic.AtomicBoolean();for(int j=0;j<200&&!ok.get();j++){Thread.sleep(100);i.runOnMainSync(()->ok.set(a.web!=null&&a.healthy&&"WS-LIVE".equals(a.web.getTitle())));}assertTrue("Silent pinned cold launch -> WebView -> WebSocket (title="+(a.web==null?"no view":"loaded")+")",ok.get());android.util.Log.i("DSH-QA","silent cold start ms="+(android.os.SystemClock.elapsedRealtime()-start));}finally{vault.clear();i.runOnMainSync(()->a.finish());i.waitForIdleSync();}
 }
}
